const e=[{Claim:"Built from the Rochester and North Kent Music and Drama Festival's own official 2026 Combined Syllabus (Chatham, Kent, England; 50th year, held 28 March 2026 at Holcombe Grammar School, adjudicator Katrina Mulvihill). This template covers 2 real classes - Audition Piece and Verse Speaking - each reproduced with its real class code, real stated time limit and real GBP entry fee straight from the syllabus.",SourceType:"Primary - Rochester and North Kent Music and Drama Festival official 2026 Syllabus PDF",Source:"https://www.rnkmdf.org.uk/wp-content/uploads/2025/10/RNKMD-Festival-Syllabus-2026.pdf",Url:"https://www.rnkmdf.org.uk/wp-content/uploads/2025/10/RNKMD-Festival-Syllabus-2026.pdf"},{Claim:"Audition Piece (classes D1-D3, 'own choice of solo dramatic performance') and Verse Speaking (S1-S3, 'own choice of verse') share an identical real 3-tier National Curriculum age ladder: NC Years 1-6, NC Years 7-9, NC Years 10-13. This same 3-tier ladder is also used by several other real classes in the syllabus's Speech and Drama section (Reading Aloud, Religious Reading, Public Speaking, Write and Perform Your Own Poem), confirming it as a genuine section-wide structure. Ages were converted using the syllabus's own General Guideline 2 ('the National Curriculum year of the performer on the day of the festival').",SourceType:"Primary - RNKMD Festival 2026 Syllabus, Speech and Drama section class listings and General Guidelines",Source:"RNKMD Festival 2026 Syllabus, pages 4, 30-32",Url:""},{Claim:"Real GBP entry fees and time limits are reproduced exactly per class: Audition Piece rises from GBP 7 (3 minutes, NC Years 1-6) to GBP 9 (5 minutes, NC Years 10-13); Verse Speaking rises from GBP 7 (2 minutes, NC Years 1-6) to GBP 9 (4 minutes, NC Years 10-13). The syllabus's own copyright note (General Guideline 9d) states that solo dramatic items and verse/prose performed to a 10-minute limit do not require copyright permission under the festival's BIFF/ALCS agreement.",SourceType:"Primary - RNKMD Festival 2026 Syllabus, Speech and Drama class-by-class fee and time-limit lines",Source:"RNKMD Festival 2026 Syllabus, pages 6, 30-32",Url:""}],a="This template covers 2 of the Speech and Drama section's roughly 20 real class families (Verse Speaking, Reading Aloud, Religious Reading, Public Speaking, Write and Perform Your Own Poem, Audition Pieces, Shakespeare Speech, Acted Scenes for small/large groups, Acted Scenes - devised drama, plus separate Adult classes SD1-SD8). Not built: Shakespeare Speech (D4-D5, real, only NC7-9/10-13 - no NC1-6 tier); Acted Scenes for small groups (D6, real, NC Years 3-6 only, a single tier rather than the 3-tier ladder); Acted Scenes for small/large groups and devised drama (D7-D12, real, each only NC7-9/10-13, missing the youngest tier) - all genuine buildable follow-ups with narrower real age coverage than Audition Piece/Verse Speaking. The Adult-only classes (SD1-SD8) form a separate real family for performers aged 19+ not tied to NC years. No numeric points system beyond the BIFF percentage mark-band scale (65-95+, Developing through Exceptional) is published as a corpus-wide table, so MaximumScore uses this corpus's nominal 10-point judge scale and Ranks is left empty.",i=[{GroupName:"NC Years 1 - 6",AgeFrom:5,AgeTo:11,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/primary.webp"},{GroupName:"NC Years 7 - 9",AgeFrom:12,AgeTo:14,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/upper-primary.webp"},{GroupName:"NC Years 10 - 13",AgeFrom:15,AgeTo:18,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/teen.webp"}],t=[{CompetitionItem:0,Title:"Audition Piece",Category:42,CategoryCategoryName:"Action",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/monologue.webp"},{CompetitionItem:0,Title:"Verse Speaking",Category:110,CategoryCategoryName:"Literary",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/solo-verse.webp"}],r=[{CompetitionItem:0,CompetitionItemTitle:"Audition Piece",Group:0,GroupGroupName:"NC Years 1 - 6",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:7,MaximumMinutes:3,MaximumScore:10,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,TimeCalculation:"PerHead"},{CompetitionItem:0,CompetitionItemTitle:"Audition Piece",Group:0,GroupGroupName:"NC Years 7 - 9",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:7,MaximumMinutes:4,MaximumScore:10,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:2,TimeCalculation:"PerHead"},{CompetitionItem:0,CompetitionItemTitle:"Audition Piece",Group:0,GroupGroupName:"NC Years 10 - 13",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:9,MaximumMinutes:5,MaximumScore:10,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:3,TimeCalculation:"PerHead"},{CompetitionItem:0,CompetitionItemTitle:"Verse Speaking",Group:0,GroupGroupName:"NC Years 1 - 6",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:7,MaximumMinutes:2,MaximumScore:10,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:4,TimeCalculation:"PerHead"},{CompetitionItem:0,CompetitionItemTitle:"Verse Speaking",Group:0,GroupGroupName:"NC Years 7 - 9",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:7,MaximumMinutes:3,MaximumScore:10,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:5,TimeCalculation:"PerHead"},{CompetitionItem:0,CompetitionItemTitle:"Verse Speaking",Group:0,GroupGroupName:"NC Years 10 - 13",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:9,MaximumMinutes:4,MaximumScore:10,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:6,TimeCalculation:"PerHead"}],n=[],o=[],s={Evidence:e,MaintenanceNote:a,AgeWiseGroups:i,CompetitionItems:t,CompetitionsAssignedToGroup:r,Grades:n,Ranks:o};export{i as AgeWiseGroups,t as CompetitionItems,r as CompetitionsAssignedToGroup,e as Evidence,n as Grades,a as MaintenanceNote,o as Ranks,s as default};
